/**
 * src/config/emojiHelper.js
 * Central lookup for Nhiễm Nhiễm Application Emojis (<a:su_...:id> / <:su_...:id>).
 * Reads src/config/custom_emojis.json generated by scripts/upload_125_app_emojis.mjs.
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const EMOJI_MAP_PATH = path.join(__dirname, 'custom_emojis.json');

let emojiMap = {};
try {
  if (fs.existsSync(EMOJI_MAP_PATH)) {
    emojiMap = JSON.parse(fs.readFileSync(EMOJI_MAP_PATH, 'utf8'));
  }
} catch (err) {
  console.warn('[EmojiHelper] Failed to load custom_emojis.json:', err.message);
  emojiMap = {};
}

export function reloadEmojiMap() {
  if (fs.existsSync(EMOJI_MAP_PATH)) {
    emojiMap = JSON.parse(fs.readFileSync(EMOJI_MAP_PATH, 'utf8'));
  }
  return emojiMap;
}

export const LEGACY_TO_UID_ALIAS = {
  su_fox_mascot: 'cuu_vi_hong_ho',
  su_frame_token: 'frame_unlock_token',
  su_enchant_stone: 'enchant_stone',
  su_star_stone: 'pet_star_stone',
  su_ticket_equip: 'gacha_ticket_equip',
  su_ticket_pet: 'gacha_ticket_pet',
  su_tower_reset_card: 'tower_reset_card',
  su_title_card: 'title_rename_card',
  su_ring_pham: 'ring_common',
  su_ring_linh: 'ring_rare',
  su_ring_tien: 'ring_epic',
  su_ring_thanthoai: 'ring_mythic',
};

const UID_TO_LEGACY_ALIAS = Object.fromEntries(
  Object.entries(LEGACY_TO_UID_ALIAS).map(([k, v]) => [v, k]),
);

export function getEmojiEntry(name) {
  if (!name) return null;
  const key = String(name).trim();
  if (!key) return null;

  if (emojiMap[key]) return emojiMap[key];

  const mappedAlias = LEGACY_TO_UID_ALIAS[key];
  if (mappedAlias && emojiMap[mappedAlias]) return emojiMap[mappedAlias];

  if (key.startsWith('su_pet_')) {
    const stripped = key.slice('su_pet_'.length);
    if (emojiMap[stripped]) return emojiMap[stripped];
  }
  if (key.startsWith('su_')) {
    const stripped = key.slice('su_'.length);
    if (emojiMap[stripped]) return emojiMap[stripped];
  }

  const mappedLegacy = UID_TO_LEGACY_ALIAS[key];
  if (mappedLegacy && emojiMap[mappedLegacy]) return emojiMap[mappedLegacy];

  if (!key.startsWith('su_')) {
    if (emojiMap[`su_${key}`]) return emojiMap[`su_${key}`];
    if (emojiMap[`su_pet_${key}`]) return emojiMap[`su_pet_${key}`];
  }

  return null;
}

/**
 * Returns Discord tag (<a:name:id> or <:name:id>) preferring animated GIFs.
 */
export function em(name, fallback = '') {
  const entry = getEmojiEntry(name);
  if (entry?.tag) return entry.tag;
  if (entry?.id && entry?.name) {
    return entry.animated ? `<a:${entry.name}:${entry.id}>` : `<:${entry.name}:${entry.id}>`;
  }
  return fallback;
}

/**
 * Returns raw Discord emoji snowflake ID (or empty string if missing).
 */
export function emId(name) {
  const entry = getEmojiEntry(name);
  return entry?.id || '';
}

export function tierEmojiKey(rarityKey) {
  switch (String(rarityKey || '').toLowerCase()) {
    case 'evolved_supreme':
    case 'unique_supreme':
    case 'supreme': return 'su_tier_toithuong';
    case 'mythic': return 'su_tier_thanthoai';
    case 'epic': return 'su_tier_tien';
    case 'rare': return 'su_tier_linh';
    default: return 'su_tier_pham';
  }
}

export function tierEmoji(rarityKey, fallback = '') {
  return em(tierEmojiKey(rarityKey), fallback);
}

export function roleTierEmojiKey(rarityKey) {
  switch (String(rarityKey || '').toLowerCase()) {
    case 'evolved_supreme':
    case 'unique_supreme':
    case 'mythic':
    case 'supreme': return 'su_role_tier_mythic';
    case 'epic': return 'su_role_tier_epic';
    case 'rare': return 'su_role_tier_rare';
    default: return 'su_role_tier_common';
  }
}

export function roleTierEmoji(rarityKey, fallback = '') {
  return em(roleTierEmojiKey(rarityKey), fallback || em('su_realm_star'));
}

export function elementEmojiKey(element) {
  const raw = String(element || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd');
  if (raw.includes('kim')) return 'su_el_kim';
  if (raw.includes('moc')) return 'su_el_moc';
  if (raw.includes('thuy')) return 'su_el_thuy';
  if (raw.includes('hoa')) return 'su_el_hoa';
  if (raw.includes('tho')) return 'su_el_tho';
  if (raw.includes('loi')) return 'su_el_loi';
  if (raw.includes('quang')) return 'su_el_quang';
  if (raw.includes('am')) return 'su_el_am';
  return 'su_el_hondon';
}

export function elementEmoji(element, fallback = '') {
  return em(elementEmojiKey(element), fallback);
}

export function itemEmojiKey(itemId) {
  return itemId ? String(itemId).trim() : '';
}

export function itemEmoji(itemId, fallback = '') {
  return em(itemEmojiKey(itemId), fallback);
}

export function petEmojiKey(petType) {
  return petType ? String(petType).trim() : '';
}

export function petEmoji(petType, fallback = '') {
  return em(petEmojiKey(petType), fallback);
}

export function ringEmojiKey(ringIdOrRarity) {
  const s = String(ringIdOrRarity || '').toLowerCase();
  if (s.includes('mythic') || s.includes('than')) return 'ring_mythic';
  if (s.includes('epic') || s.includes('tien')) return 'ring_epic';
  if (s.includes('rare') || s.includes('linh')) return 'ring_rare';
  return 'ring_common';
}

export function domainEmojiKey(domainId) {
  return domainId ? String(domainId).trim() : '';
}

export function domainEmoji(domainId, fallback = '') {
  return em(domainEmojiKey(domainId), fallback);
}

export function domainElementEmojiKey(element) {
  const raw = String(element || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').replace(/đ/g, 'd');
  if (raw.includes('kiem')) return 'domain_unique_1';
  if (raw.includes('huyen')) return 'domain_unique_2';
  if (raw.includes('tran')) return 'domain_unique_3';
  if (raw.includes('minh')) return 'domain_unique_4';
  if (raw.includes('thanh')) return 'domain_unique_5';
  if (raw.includes('hon don')) return 'domain_fuyumi_cuu_vi_hong_mong';
  return 'su_realm_star';
}

export function domainElementEmoji(element, fallback = '') {
  return em(domainElementEmojiKey(element), fallback || em('su_realm_star'));
}

export function senseEmojiKey(senseId) {
  return senseId ? String(senseId).trim() : '';
}

export function senseEmoji(senseId, fallback = '') {
  return em(senseEmojiKey(senseId), fallback);
}

export function realmEmojiKeyById(realmId) {
  return realmId ? String(realmId).trim() : '';
}

export function realmEmojiById(realmId, fallback = '') {
  return em(realmEmojiKeyById(realmId), fallback);
}

export function farmEmoji(farmId, fallback = '') {
  return farmId ? em(String(farmId).trim(), fallback) : fallback;
}

export function minigameEmoji(mgId, fallback = '') {
  return mgId ? em(String(mgId).trim(), fallback) : fallback;
}

export function ringEmoji(ringIdOrRarity, fallback = '') {
  return em(ringEmojiKey(ringIdOrRarity), fallback);
}

export function realmEmojiKey(level) {
  const lv = Number(level) || 1;
  if (lv >= 100) return 'su_realm_7_hondondao';
  if (lv >= 90) return 'su_realm_6_daithua';
  if (lv >= 80) return 'su_realm_5_hoathan';
  if (lv >= 60) return 'su_realm_4_nguyenanh';
  if (lv >= 40) return 'su_realm_3_kimdan';
  if (lv >= 20) return 'su_realm_2_trucco';
  return 'su_realm_1_luyenkhi';
}

export function realmEmoji(level, fallback = '') {
  return em(realmEmojiKey(level), fallback);
}

export function levelMilestoneEmojiKey(level) {
  const lv = Number(level) || 5;
  const known = [100, 80, 60, 45, 35, 20, 10, 5];
  const matched = known.find((m) => lv >= m) || 5;
  return matched === 10 ? 'su_lv15' : `su_lv${matched}`;
}

export function levelMilestoneEmoji(level, fallback = '') {
  return em(levelMilestoneEmojiKey(level), fallback);
}

export function gradeEmojiKey(grade) {
  const g = String(grade || 'D').trim().toUpperCase();
  if (['D', 'C', 'B', 'A', 'S'].includes(g)) {
    return `su_grade_${g.toLowerCase()}`;
  }
  return 'su_grade_d';
}

export function gradeEmoji(grade, fallback = '') {
  const g = String(grade || 'D').trim().toUpperCase();
  const valid = ['D', 'C', 'B', 'A', 'S'].includes(g) ? g : 'D';
  return em(gradeEmojiKey(valid), fallback || `[${valid}]`);
}

/**
 * Fallback an toàn 0% Unicode Windows cho các Emoji UI v1.5:
 * Trước khi upload PNG (Nhịp 1), fallback về custom emoji SuMi sẵn có hoặc ký hiệu ASCII sạch;
 * sau khi upload PNG (Nhịp 2), tự động trả về custom emoji <:ui_...:id> từ custom_emojis.json.
 */
